<?php
declare(strict_types=1);require __DIR__.'/_init.php';try{if($_SERVER['REQUEST_METHOD']==='GET'){$rows=$pdo->query('SELECT p.*,i.name item_name,i.sku,s.name supplier_name FROM purchase_orders p JOIN items i ON i.id=p.item_id JOIN suppliers s ON s.id=p.supplier_id ORDER BY p.id DESC LIMIT 300')->fetchAll();json_response(true,$rows);} $d=request_json();$action=(string)($d['action']??'create');if($action==='status'){$id=positive_int($d['id']??null,'id');$status=(string)($d['status']??'');if(!in_array($status,['Pending','Ordered','Received','Cancelled'],true))json_response(false,null,'VALIDATION_ERROR','Invalid order status.',[],422);$q=$pdo->prepare('UPDATE purchase_orders SET status=?,updated_at=NOW() WHERE id=?');$q->execute([$status,$id]);json_response(true,['updated'=>$q->rowCount()]);}$item=positive_int($d['item_id']??null,'item_id');$supplier=positive_int($d['supplier_id']??null,'supplier_id');$qty=positive_int($d['quantity']??null,'quantity');$cost=max(0,(float)($d['unit_cost']??0));$expected=trim((string)($d['expected_date']??''));$expected=$expected!==''?$expected:null;$notes=trim((string)($d['notes']??''))?:null;$orderNo='PO-'.date('Ymd').'-'.strtoupper(bin2hex(random_bytes(3)));$pdo->prepare("INSERT INTO purchase_orders(order_no,item_id,supplier_id,quantity,unit_cost,expected_date,notes,status,created_by) VALUES(?,?,?,?,?,?,?,'Pending',?)")->execute([$orderNo,$item,$supplier,$qty,$cost,$expected,$notes,(int)$user['id']]);json_response(true,['id'=>(int)$pdo->lastInsertId()],null,'Purchase order created.',[],201);}catch(PDOException $e){if((string)$e->getCode()==='23000')json_response(false,null,'CONFLICT','Selected product or supplier does not exist.',[],409);api_error($e);}catch(Throwable $e){api_error($e);}
